/** An organisation that publishes or is reported on. */
export interface ActorConfig {
	id: string;
	name: string;
	kind: ActorKind;
	/** The lane where this actor is usually found. */
	lane: string;
	/** Bare host, such as gov.wales. */
	domain?: string | null;
}

/** The kind of an organisation. */
export type ActorKind = "government" | "legislature" | "regulator" | "public_body" | "research" | "ngo" | "business" | "union" | "media" | "international" | "other";

/** config/reference/actors.json: the actor catalogue. */
export interface ActorsFile {
	notes?: string | null;
	actors: ActorConfig[];
}

/** Which way the report bears on one requirement. */
export interface AssessmentEntry {
	/** A requirement id from skill/REFERENCE.md, such as si4. */
	requirement_id: string;
	direction: Direction;
}

/** Where a report goes next. */
export type Bucket = "brief" | "follow_up" | "watch" | "park";

/** One candidate: a gated, deduplicated hit, one per canonical URL in the run. */
export interface CandidateEntry {
	candidate_id: string;
	status: CandidateStatus;
	/** The URL as first found, before canonicalising. */
	url: string;
	/** The canonical URL: no scheme, www, fragment or tracking. */
	canonical_url: string;
	title: string;
	snippet: string;
	published_on: string | null;
	/** The run that first recorded this URL. */
	first_seen_run_id: string;
	/** The watched source, or null for the open web. */
	source_id: string | null;
	lane: string;
	discipline: Discipline;
	/** The query whose hit found this URL first. */
	query_id: string;
	/** Hints from the queries; not tags. */
	requirement_hints: string[];
	/** Hints from the queries; not tags. */
	topic_hints: string[];
	trusted: boolean;
}

/** What the collector knew about a candidate's canonical URL when it found it. */
export type CandidateStatus = "new" | "seen_before" | "reinforcement";

/** data/candidates/<run_id>.json: everything one completed scan run found. */
export interface CandidatesFile {
	/** Always gwylio.candidates/1. */
	format: "gwylio.candidates/1";
	/** A scan run id. */
	run_id: string;
	/** complete, or aborted when a collector failed: then nothing was kept. */
	run_status?: "complete" | "aborted";
	instrument_version: string;
	instrument_hash: string;
	generated_at: string;
	started_at: string;
	finished_at: string;
	disciplines_run: Discipline[];
	max_requests_per_run: number;
	requests_made: number;
	budget_exhausted: boolean;
	funnel: FunnelCounts;
	/** What the run says about itself, such as the budget. */
	notes: string[];
	/** Soft failures the collectors reported. */
	warnings: string[];
	candidates: CandidateEntry[];
	reinforcements: ReinforcementEntry[];
	sightings: SightingEntry[];
}

/** The state of one requirement in the picture. */
export type CoverageStatus = "covered" | "thin" | "quiet" | "blind_spot";

/**
 * The Admiralty credibility of one report's information, 1 (best) to 6 (cannot be judged).
 *
 * The analyst judges credibility per report; the source's reliability is
 * fixed by the watchlist. The two together make the grading, such as B2.
 */
export type Credibility = 1 | 2 | 3 | 4 | 5 | 6;

/** config/datecheck.json: the rules gwylio datecheck applies. */
export interface DatecheckFile {
	notes?: string | null;
	/** Future-framed phrases that rot once their date passes, matched as words. */
	future_phrases: string[];
	/** A verification older than this many days is stale. */
	stale_after_days?: number;
}

/** Which way a report bears on one requirement. */
export type Direction = "supports" | "threatens" | "neutral" | "informs_baseline";

/** The kind of collection a collector performs. */
export type Discipline = "osint_web" | "osint_feed" | "osint_site" | "osint_academic" | "geoint" | "sensor";

/** The fate of one candidate. */
export interface DispositionEntry {
	candidate_id: string;
	outcome: DispositionOutcome;
	/** One sentence: which part of the promotion test decided. */
	reason: string;
	/** promoted: the new report; reinforcement: the report it reinforces; duplicate: optionally, the report it duplicates. */
	report_id?: string | null;
}

/** The fate the analyst gives one candidate in a submission. */
export type DispositionOutcome = "promoted" | "rejected" | "duplicate" | "deferred" | "reinforcement";

/** One report the sweep faded, and the reason recorded in its history. */
export interface FadeEntry {
	report_id: string;
	change: string;
}

/** What the date check found wrong with a report. */
export type FindingKind = "passed_horizon" | "future_language" | "stale_verification" | "never_verified";

/**
 * How many hits survived each stage of the run.
 *
 * raw = dropped_own + dropped_negative + dropped_unrelated + passed, and
 * unique = new + seen_before + reinforcements.
 */
export interface FunnelCounts {
	raw: number;
	dropped_own: number;
	dropped_negative: number;
	dropped_unrelated: number;
	/** Hits that passed every gate and reached deduplication. */
	passed: number;
	/** Candidates: passed hits grouped by canonical URL. */
	unique: number;
	seen_before: number;
	new: number;
	reinforcements: number;
}

/** config/gating.json: own domains and relevance tokens for the gates. */
export interface GatingFile {
	notes?: string | null;
	/** The organisation's own domains: hits on them are dropped. */
	own_domains: string[];
	/** Lower-case words or phrases that make an untrusted hit relevant. */
	relevance_tokens: string[];
	/** Places of these kinds add their English and Welsh names as tokens. */
	relevance_place_kinds?: PlaceKind[];
}

/** What a requirement group stands for. */
export type GroupKind = "impact" | "wbo";

/** A named threat to the Welsh environment. */
export interface HazardConfig {
	id: string;
	name: string;
	/** A node id on the hazard-families taxonomy axis. */
	family: string;
	note?: string | null;
}

/** config/reference/hazards.json: the hazard catalogue. */
export interface HazardsFile {
	notes?: string | null;
	hazards: HazardConfig[];
}

/** What one history entry records. */
export type HistoryKind = "created" | "sighted" | "state_changed" | "verified" | "updated" | "imported" | "faded" | "revived";

/** Where a report is in the indications and warnings lifecycle. */
export type IndicatorState = "emerging" | "tracking" | "reinforced" | "matured" | "faded" | "parked";

/** config/instrument.json: the versioned query instrument. */
export interface InstrumentFile {
	notes?: string | null;
	/** Such as 2026.10.0. */
	version: string;
	/** sha256 of the canonical JSON of every field except notes and this one. */
	content_hash: string;
	global_negative_terms?: string[];
	/** The request budget of one scan run. */
	max_requests_per_run: number;
	queries: QueryConfig[];
}

/** Where we look: a grouping of sources under one lens. */
export interface LaneConfig {
	id: string;
	name: string;
	lens: Lens;
	/** One sentence on what the lane watches. */
	description: string;
}

/** config/lanes.json: the collection lanes. */
export interface LanesFile {
	notes?: string | null;
	lanes: LaneConfig[];
}

/** The three viewpoints the commission asked for; every lane sits under one. */
export type Lens = "government" | "partnership_society" | "international";

/** A three-point score: low, medium or high. */
export type Level = "low" | "medium" | "high";

/** How a candidate was matched to an existing intelligence report. */
